INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1027, '数学', '三年级', '填空', 2, '{"stem": "73粒糖平均分给5人，每人能分到多少粒，还剩多少粒？小海想：每人先分10粒，5×10=（　）粒，还剩73−50=（　）粒；再把剩下的平均分，23÷5=（　）……（　），每人共分到10+4=（　）粒。所以73÷5=（　）……（　）。", "options": null}', '50；23；4；3；14；14……3', '每人先分10粒，用去5×10=50粒；还剩73−50=23粒；23÷5每人再分4粒，用去4×5=20粒，还剩3粒（余数3＜除数5）；每人共10+4=14粒。所以73÷5=14……3。', 'paper', '["practice", "ykl3sx", "4.2"]', '["paper_png/ykl3_sx/p067.png"]', 0);

